WITH flattened_attrs AS (SELECT id, effective_from, currency, tier_prices, discounts, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers) SELECT DATE_TRUNC('MONTH', effective_from) AS activity_month, CASE WHEN avg_tier_price >= 24 THEN 'PREMIUM' ELSE 'STANDARD' END AS avg_tier_price_tier, PERCENTILE_APPROX(avg_tier_price, 0.5) AS avg_tier_price_p50, SUM(lowest_price) FILTER (WHERE currency = 'USD') AS usd_total_lowest_price, COUNT(*) AS event_count FROM flattened_attrs GROUP BY 1, 2 ORDER BY avg_tier_price_tier NULLS FIRST
